/** The spell of a card (and of its Maxima: null — none of its own). */
export const cardSpell = (s) => matchSpell(s.name);
function maximaOf(s) {
    const base = cardSpell(s);
    if (!s.max || !base) return null;
    const m = matchSpell(`${s.name} Максима`);
    return m && m !== base && /Maxima$/.test(m) ? m : null;
}

/** «✅ Известно с начала» / «📜 Со свитка» (how it is learned outside Creative; in Creative all is known). */
const LEARN = {
    start: ['learn-start', '✅ Известно с начала'],
    scroll: ['learn-scroll', '📜 Со свитка'],
    book: ['learn-scroll', '📖 Из книги птицы-книги'],
    mana: ['learn-scroll', '✨ Дар богов: при 1000 ячеек маны'],
};
export function learnBadge(spell, cat = null) {
    if (!spell) return '';
    let [cls, text] = LEARN[howLearned(spell)];
    if (spell === 'Flight') text = '📖 В «Выживании» — из быстрой книги-птицы';
    else if (spell === 'CreateBoard') text = '📜 Со свитка или из книги птицы-книги';
    else if (cat === 'gods' && howLearned(spell) !== 'mana') text = '🪐 Со свитка храма богов';
    else if (text === LEARN.scroll[1] && teachKey(spell) !== spell) text = `📜 Со свитка «${SPELLS.find((x) => cardSpell(x) === teachKey(spell))?.name || teachKey(spell)}»`;
    return `<span class="learn-badge ${cls}">${text}</span>`;
}

/**
 * The pause menu's mark on a spell (`used(spell)`: its first success already paid — Mana.spellsUsed): ✅ the mana for
 * it is had, ☐ +N — not yet (the author: «чтобы я понимал, за какое заклинание я уже получил очки маны, а за какое нет»).
 */
function manaMark(spell, used) {
    if (!used || !spell) return '';
    const n = firstSpellGain(spell);
    if (!n) return '';
    return used(SAME_SPELL[spell] || spell)
        ? `<span class='learn-badge mana-done' title='Ячейки маны за первое удачное заклинание уже получены'>✅ мана получена</span>`
        : `<span class='learn-badge mana-wait' title='Произнесите его удачно хотя бы раз — получите ячейки маны'>☐ +${n} к мане</span>`;
}

export function card(item, can = null, used = null) {
    const el = document.createElement('div');
    el.className = 'item-card';
    const stat = (label, v) => (v && v !== '—' ? `<div class='stat-row'><span>${label}:</span><span class='stat-val'>${v}</span></div>` : '');
    const stats = stat('Урон', item.dmg) + stat('Мана', item.cost);
    const spell = item.say ? cardSpell(item) : null, maxSpell = item.say ? maximaOf(item) : null;
    const maxShown = item.max && !(maxSpell && can && !can(maxSpell)); // (the pause menu: a Maxima the hero doesn't know is left out)
    el.innerHTML = `
        <img src='${item.icon}' class='item-icon' onerror="this.style.display='none'">
        <div class='item-name'>${item.name}</div>
        ${spell ? `<div class='item-learn'>${learnBadge(spell, item.cat)} ${manaMark(spell, used)}</div>` : ''}
        <div class='item-desc'>${item.desc}</div>
        ${item.say ? `<div class='item-desc'><b>Как:</b> ${item.say}</div>` : ''}
        ${item.next ? `<div class='item-desc'><b>Дальше:</b> ${item.next}</div>` : ''}
        ${maxShown ? `<div class='item-desc item-max'><b>⚡ Максима</b> ${maxSpell ? learnBadge(maxSpell, item.cat) + ' ' + manaMark(maxSpell, used) : ''}<br>${item.max}</div>` : ''}
        ${item.magic ? `<div class='item-desc item-max'><b>✨ Бывает волшебным:</b> ${item.magic}</div>` : ''}
        ${stats ? `<div class='item-stats'>${stats}</div>` : ''}`;
    return el;
}

/** Category buttons over a grid (spells and items share the look). */
function renderCats(catsId, gridId, cats, list, current, pick, can = null, used = null) {
    const box = document.getElementById(catsId);
    const grid = document.getElementById(gridId);
    if (!box || !grid) return;
    box.innerHTML = '';
    for (const c of cats) {
        const b = document.createElement('button');
        b.className = 'sub-tab' + (c.id === current ? ' active' : '');
        b.textContent = `${c.name} (${c.id === 'all' ? list.length : list.filter((s) => s.cat === c.id).length})`;
        b.onclick = () => pick(c.id);
        box.appendChild(b);
    }
    grid.innerHTML = '';
    for (const s of list.filter((x) => current === 'all' || x.cat === current)) grid.appendChild(card(s, can, used));
}

let currentCat = 'all';
let currentItemCat = 'weapon';

/**
 * The spell book: in the menu and in the game's pause menu. `can(spellId)` — only the spells the hero can say
 * now (outside Creative: the game's own «knows it» check — SpellBook.js), the empty sections left out.
 */
export function renderSpellsTab(catsId = 'spell-cats', gridId = 'spells-grid', can = null, used = null) {
    const list = can ? SPELLS.filter((s) => can(cardSpell(s))) : SPELLS;
    const cats = [{ id: 'all', name: '✨ Все' }, ...(can ? SPELL_CATEGORIES.filter((c) => list.some((s) => s.cat === c.id)) : SPELL_CATEGORIES)];
    if (cats.length && !cats.some((c) => c.id === currentCat)) currentCat = cats[0].id;
    renderCats(catsId, gridId, cats, list, currentCat, (id) => { currentCat = id; renderSpellsTab(catsId, gridId, can, used); }, can, used);
}

export function renderItemsTab(extra = []) {
    const known = new Set(ITEM_CATEGORIES.map((c) => c.id));
    const list = [...ITEMS, ...extra].filter((it) => it.cat !== 'potions').map((it) => (known.has(it.cat) ? it : { ...it, cat: 'things' }));
    renderCats('item-cats', 'items-grid', ITEM_CATEGORIES, list, currentItemCat, (id) => { currentItemCat = id; renderItemsTab(extra); });
}

/** «Механика игры»: plain sections — an icon, a title, a lead line and points. */
export function renderMechanicsTab() {
    const box = document.getElementById('mechanics-list');
    if (!box) return;
    box.innerHTML = MECHANICS.map((m) => `
        <section class="mech-card">
            <h3 class="mech-title"><span class="mech-icon">${m.icon}</span>${m.title}</h3>
            <p class="mech-lead">${m.lead}</p>
            <ul class="mech-points">${m.points.map((p) => `<li>${p}</li>`).join('')}</ul>
        </section>`).join('');
}

